With Euler's formula to represent pure frequencies in mind, a trigonometric polynomial can be expressed as
\begin{equation} s_N(x):= \sum_{n=-N}^N c_n e^{inx} \ .
\end{equation}

Let
\begin{equation}
    a\ge 4
\end{equation}
be a natural number that as it gets larger will allow for more general applications of Theorem \ref{metric-space-Carleson}
but will worsen the constants in the estimates.

A one-sided Calder\'on--Zygmund kernel $K$ on the doubling metric measure space $(X, \rho, \mu, a)$ is a measurable function
\begin{equation} K:X\times X\to \mathbb{C}
\end{equation}
such that for all $x,y',y\in X$ with $x\neq y$, we have
\begin{equation} |K(x,y)| \leq \frac{2^{a^3}}{V(x,y)}
\end{equation}
and if $2\rho(y,y') \leq \rho(x,y)$, then
\begin{equation} |K(x,y) - K(x,y')| \leq \left(\frac{\rho(y,y')}{\rho(x,y)}\right)^{\frac{1}{a}}\frac{2^{a^3}}{V(x,y)},
\end{equation}
where \[V(x,y):=\mu(B(x,\rho(x,y))).\]

Define the maximally truncated non-tangential singular integral $T_{*}$ associated with $K$ by
\begin{equation} T_{*}f(x):=\sup_{R_1 < R_2} \sup_{\rho(x,x')<R_1} \left|\int_{R_1< \rho(x',y) < R_2} K(x',y) f(y) \, \mathrm{d}\mu(y) \right|\,.
\end{equation}

For a Borel function ${Q}:X\to {\Theta}$, and ${\vartheta} \in {\Theta}$ and $x\in X$ define
\begin{equation}
    R_{{Q}}({\vartheta},x)=\sup\{r>0:d_{B(x,r)}({\vartheta}, {Q}(x))<1\}
\end{equation}
and define further
\begin{equation} T_{{Q}}^{\vartheta} f(x):=\sup_{R_1<R_2} \ \sup_{\rho(x,x')<R_1}
    \left|\int_{R_1< \rho(x',y) < \min\{R_2, R_{{Q}}({\vartheta},x')\}} K(x',y) f(y) \, \mathrm{d}\mu(y) \right|
\end{equation}

Define
\begin{equation} D:= 2^{100 a^2}\, ,
\end{equation}
\begin{equation} \kappa:= 2^{-10a}\,,
\end{equation}
and
\begin{equation} Z := 2^{12a}\,.
\end{equation}

A tile structure $({\mathfrak P},{\mathcal{I}},{\Omega},{\mathcal{Q}},{\mathrm{c}},{\mathrm{s}})$
for a given grid structure $(\mathcal{D}, c, s)$
is a finite set ${\mathfrak P}$ of elements called tiles with five maps
\begin{align*}
    {\mathcal{I}}&\colon {\mathfrak P}\to {\mathcal{D}}\\
    {\Omega}&\colon {\mathfrak P}\to \mathcal{P}({\Theta}) \\
    {\mathcal{Q}} &\colon {\mathfrak P}\to {Q}(X)\\
    {\mathrm{c}} &\colon {\mathfrak P}\to X\\
    {\mathrm{s}} &\colon {\mathfrak P}\to \mathbb{Z}
\end{align*}
with ${\mathcal{I}}$ surjective and $\mathcal{P}({\Theta})$ denoting the power set of ${\Theta}$ such that the five properties \eqref{eq-dis-freq-cover}, \eqref{eq-freq-dyadic},
\eqref{eq-freq-comp-ball}, \eqref{tilecenter}, and
\eqref{tilescale} hold.
For each dyadic cube $I$, the restriction of the map $\Omega$ to the set
\begin{equation} {\mathfrak P}(I)=\{{\mathfrak p}: {\mathcal{I}}({\mathfrak p}) =I\}
\end{equation}
is injective
and we have the disjoint covering property (we use the union symbol with dot on top to denote a disjoint union)
\begin{equation} {Q}(X)\subset \dot{\bigcup}_{{\mathfrak p}\in {\mathfrak P}(I)}{\Omega}({\mathfrak p}).
\end{equation}
For any tiles ${\mathfrak p},{\mathfrak q}$ with ${\mathcal{I}}({\mathfrak p})\subset {\mathcal{I}}({\mathfrak q})$ and ${\Omega}({\mathfrak p}) \cap {\Omega}({\mathfrak q}) \neq \emptyset$ we have
\begin{equation} {\Omega}({\mathfrak q})\subset {\Omega}({\mathfrak p}) .
\end{equation}
For each tile ${\mathfrak p}$,
\begin{equation} {\mathcal{Q}}({\mathfrak p})\in B_{{\mathfrak p}}({\mathcal{Q}}({\mathfrak p}), 0.2) \subset {\Omega}({\mathfrak p}) \subset B_{{\mathfrak p}}({\mathcal{Q}}({\mathfrak p}),1)\,,
\end{equation}
where
\begin{equation}
    B_{{\mathfrak p}} ({\vartheta}, R) := \{{\theta} \in {\Theta} \, : \, d_{{\mathfrak p}}({\vartheta}, {\theta}) < R\,\} ,
\end{equation}
and
\begin{equation} d_{{\mathfrak p}} := d_{B({\mathrm{c}}({\mathfrak p}),\frac 14 D^{{\mathrm{s}}({\mathfrak p})})}\, .
\end{equation}
We have for each tile ${\mathfrak p}$
\begin{equation} {\mathrm{c}}({\mathfrak p})=c({\mathcal{I}}({\mathfrak p})),
\end{equation}
\begin{equation} {\mathrm{s}}({\mathfrak p})=s({\mathcal{I}}({\mathfrak p})).
\end{equation}

For each dyadic cube $I$, the restriction of the map $\Omega$ to the set
\begin{equation} {\mathfrak P}(I)=\{{\mathfrak p}: {\mathcal{I}}({\mathfrak p}) =I\}
\end{equation}
is injective
and we have the disjoint covering property (we use the union symbol with dot on top to denote a disjoint union)
\begin{equation} {Q}(X)\subset \dot{\bigcup}_{{\mathfrak p}\in {\mathfrak P}(I)}{\Omega}({\mathfrak p}).
\end{equation}

For each tile ${\mathfrak p}$,
\begin{equation} {\mathcal{Q}}({\mathfrak p})\in B_{{\mathfrak p}}({\mathcal{Q}}({\mathfrak p}), 0.2) \subset {\Omega}({\mathfrak p}) \subset B_{{\mathfrak p}}({\mathcal{Q}}({\mathfrak p}),1)\,,
\end{equation}
where
\begin{equation}
    B_{{\mathfrak p}} ({\vartheta}, R) := \{{\theta} \in {\Theta} \, : \, d_{{\mathfrak p}}({\vartheta}, {\theta}) < R\,\} ,
\end{equation}
and
\begin{equation} d_{{\mathfrak p}} := d_{B({\mathrm{c}}({\mathfrak p}),\frac 14 D^{{\mathrm{s}}({\mathfrak p})})}\, .
\end{equation}

We further define for $\lambda,\lambda' >0$
the relation
\begin{equation} \lambda {\mathfrak p} \lesssim \lambda' {\mathfrak p}'
\end{equation}
on ${\mathfrak P}\times {\mathfrak P}$ meaning
${\mathcal{I}}({\mathfrak p})\subset {\mathcal{I}}({\mathfrak p}')$ and
\begin{equation}
    B_{{\mathfrak p}'}({\mathcal{Q}}({\mathfrak p}'),\lambda') \subset B_{{\mathfrak p}}({\mathcal{Q}}({\mathfrak p}),\lambda)\, .
\end{equation}

Define for a tile ${\mathfrak p}$ and $\lambda>0$
\begin{equation} E_1({\mathfrak p}):=\{x\in {\mathcal{I}}({\mathfrak p})\cap G: {Q}(x)\in {\Omega}({\mathfrak p})\}\, ,
\end{equation}
\begin{equation} E_2(\lambda, {\mathfrak p}):=\{x\in {\mathcal{I}}({\mathfrak p})\cap G: {Q}(x)\in B_{{\mathfrak p}}({\mathcal{Q}}({\mathfrak p}), \lambda)\}\, .
\end{equation}

Define the densities
\begin{equation} {\operatorname{dens}}_1({\mathfrak P}') := \sup_{{\mathfrak p}'\in {\mathfrak P}'}\sup_{\lambda \geq 2} \lambda^{-a} \sup_{{\mathfrak p} \in {\mathfrak P}({\mathfrak P}'), \lambda {\mathfrak p}' \lesssim \lambda {\mathfrak p}}
    \frac{\mu({E}_2(\lambda, {\mathfrak p}))}{\mu({\mathcal{I}}({\mathfrak p}))}\, ,
\end{equation}
\begin{equation} {\operatorname{dens}}_2({\mathfrak P}') := \sup_{{\mathfrak p}'\in {\mathfrak P}'}
    \sup_{r\ge 4D^{{\mathrm{s}}({\mathfrak p})}}
    \frac{\mu(F\cap B({\mathrm{c}}({\mathfrak p}),r))}{\mu(B({\mathrm{c}}({\mathfrak p}),r))}\, .
\end{equation}

Define
\begin{equation}
    \tau:=\frac 1a\, .
\end{equation}

Define for any open ball $B$ of radius $R$ in $X$ the $L^\infty$-normalized $\tau$-H\"older norm by
\begin{equation} \|\varphi\|_{C^\tau(B)} = \sup_{x \in B} |\varphi(x)| + R^\tau \sup_{x,y \in B, x \neq y} \frac{|\varphi(x) - \varphi(y)|}{\rho(x,y)^\tau}\,.
\end{equation}

If $s(J) \ge s(I)+1$, then using the monotonicity property \eqref{monotonedb}, \eqref{defineD} and \eqref{seconddb}, we get
    \begin{equation} d_{I^\circ}({\vartheta}, {\theta}) \le d_{B(c(I), 4 D^{s(I)})}({\vartheta}, {\theta}) \le 2^{-100a} d_{B(c(I), 4D^{s(J)})}({\vartheta}, {\theta})\,.
    \end{equation}

Using \eqref{eqkernel-size} and the lower bound in \eqref{supp-Ks}
    we obtain
    \begin{equation} |K_s(x,y)|\le |K(x,y)|\le \frac{2^{a^3}}{\mu(B(x,\frac 14 D^{s-1}))}
    \end{equation}

If $2\rho(y,y') \le \rho(x,y)$, we rewrite $|K_s(x,y)-K_s(x, y')|$ as
    \begin{equation}
        |(K(x,y)-K(x,y')) \psi(D^{-s}\rho(x,y)) +
        K(x,y)(\psi(D^{-s}\rho(x,y))-\psi(D^{-s}\rho(x,y')))|\,.
    \end{equation}
    An upper bound for $|K(x,y)-K(x, y')|$ is obtained similarly to the proof of
    \eqref{eq-Ks-size}, using \eqref{eqkernel-y-smooth} and the lower bound in \eqref{supp-Ks}
    \begin{equation}
        |K(x,y)-K(x, y')|\le \frac{2^{a^3}}{\mu(B(x, \frac 14 D^{s-1}))}
        \left(\frac{ \rho(y,y')}{\frac 14 D^{s-1}}\right)^{\frac 1a}\,.
    \end{equation}
    As above, this is estimated by
    \begin{equation}
       \le \frac{4D 2^{2a+101a^3}}{\mu(B(x, D^{s}))}
        \left(\frac{ \rho(y,y')}{D^{s}}\right)^{\frac 1a}
         = \frac{2^{2+2a+100a^2+101a^3}}{\mu(B(x, D^{s}))}
        \left(\frac{ \rho(y,y')}{D^{s}}\right)^{\frac 1a}\,.
    \end{equation}
    We have the trivial bound $|\psi(D^{-s}\rho(x,y))| \leq 1$, and \eqref{eq-Ks-aux}
    provides a bound for $|K(x,y)|$. Finally, we show that
    \begin{equation}
        |\psi(D^{-s}\rho(x,y))-\psi(D^{-s}\rho(x,y'))|\le
        4D \left(\frac{\rho(y, y')}{D ^ s}\right)^{\frac 1a}
    \end{equation}
    by considering separately the cases $\rho(y,y')/D^s \ge 1$ and $\rho(y,y')/D^s < 1$. In the
    former case, the inequality is trivial; in the latter case, it follows from the
    fact that $\psi$ is Lipschitz with constant $4D$.

    Combining the above bounds and using $a\ge 4$ proves \eqref{eq-Ks-smooth} when
    $2\rho(y,y') \le \rho(x,y)$.

If $2\rho(y,y') \le \rho(x,y)$, we rewrite $|K_s(x,y)-K_s(x, y')|$ as
    \begin{equation}
        |(K(x,y)-K(x,y')) \psi(D^{-s}\rho(x,y)) +
        K(x,y)(\psi(D^{-s}\rho(x,y))-\psi(D^{-s}\rho(x,y')))|\,.
    \end{equation}

An upper bound for $|K(x,y)-K(x, y')|$ is obtained similarly to the proof of
    \eqref{eq-Ks-size}, using \eqref{eqkernel-y-smooth} and the lower bound in \eqref{supp-Ks}
    \begin{equation}
        |K(x,y)-K(x, y')|\le \frac{2^{a^3}}{\mu(B(x, \frac 14 D^{s-1}))}
        \left(\frac{ \rho(y,y')}{\frac 14 D^{s-1}}\right)^{\frac 1a}\,.
    \end{equation}

As above, this is estimated by
    \begin{equation}
       \le \frac{4D 2^{2a+101a^3}}{\mu(B(x, D^{s}))}
        \left(\frac{ \rho(y,y')}{D^{s}}\right)^{\frac 1a}
         = \frac{2^{2+2a+100a^2+101a^3}}{\mu(B(x, D^{s}))}
        \left(\frac{ \rho(y,y')}{D^{s}}\right)^{\frac 1a}\,.
    \end{equation}

Finally, we show that
    \begin{equation}
        |\psi(D^{-s}\rho(x,y))-\psi(D^{-s}\rho(x,y'))|\le
        4D \left(\frac{\rho(y, y')}{D ^ s}\right)^{\frac 1a}
    \end{equation}
    by considering separately the cases $\rho(y,y')/D^s \ge 1$ and $\rho(y,y')/D^s < 1$. In the
    former case, the inequality is trivial; in the latter case, it follows from the
    fact that $\psi$ is Lipschitz with constant $4D$.

We thus express \eqref{TRR} as the sum of
\begin{equation} T_{s_1,s_2}f(x):=\sum_{s_1 \le s\le s_2}
\int K_s(x,y) f(y) e(Q(x)(y)) \, \mathrm{d}\mu(y)
\end{equation}
and
\begin{equation} \sum_{s=s_1-2,s_1-1, s_2+1, s_2+2}
\int_{R_1 < \rho(x,y) < R_2} K_s(x,y) f(y) e(Q(x)(y)) \,
 \mathrm{d}\mu(y),
\end{equation}

To handle the case \eqref{boundarys}, we use the triangle inequality and the properties \eqref{supp-Ks}, \eqref{eq-Ks-size} of $K_s$  and $|f| \le \mathbf{1}_F$ to obtain for arbitrary $s$ the inequality
\begin{multline}
\left|\int_{R_1 < \rho(x,y) < R_2} K_s(x,y) f(y) e(Q(x)(y)) \, \mathrm{d}\mu(y)\right|\\
\leq \frac{2^{102 a^3}}{\mu(B(x, D^{s}))}
 \int_{B(x, D^s)} \mathbf{1}_F(y) \, \mathrm{d}\mu(y)
\leq 2^{102 a^3} M\mathbf{1}_F(x),
\end{multline}
where $M\mathbf{1}_F$ is as defined in \Cref{Hardy-Littlewood}.

With these choices, and noting that with the definition of $T_{2, \sigma_1, \sigma_2}$ from \eqref{middles1}
    \begin{equation*}
    T_{\sigma_1(x),\sigma_2(x)} f(x)=T_{2,\sigma_1,\sigma_2} f(x),
    \end{equation*}
    we conclude that the left-hand side of \eqref{Scut} and \eqref{Sqlin} are equal.

Fix $\sigma_1$, $\sigma_2$ and ${Q}$ as in the lemma. Applying \Cref{finitary-Carleson} recursively, we obtain a sequence of sets $G_n$ with $G_0=G$ and, for each $n\ge 0$, $G_{n+1} \subset G_n$, $\mu(G_{n})\le 2^{-n} \mu(G)$ and
\begin{equation*}
    \int \mathbf{1}_{G_{n}\setminus G_{n+1}}(x)
    \left| {T}_{2,\sigma_1,\sigma_2} f(x) \right|\, d\mu(x)
\end{equation*}
\begin{equation}
    \le \frac{2^{442a^3}}{(q-1)^5} \mu(G_n)^{1 - \frac{1}{q}} \mu(F)^{\frac{1}{q}}.
\end{equation}

Let $k$ and $Y$ be given. By applying the doubling property \eqref{doublingx} inductively, we have for each integer $j\ge 0$
\begin{equation} \mu(B(y,2^{j}D^k))\le 2^{aj} \mu(B(y,D^k))\, .
\end{equation}

Applying \eqref{jballs} for $j' = \ln_2(8D^{2S}) = 3 + 2S \cdot 100a^2$ by \eqref{defineD}, using $-S\le k\le S$, $y\in B(o,4D^S)$, and the triangle inequality, we have
\begin{equation}
    B(o, 4D^S) \subset B(y, 8D^S) \subset B(y,2^{j'}D^k) \, .
\end{equation}

Using the disjointedness of the balls in \eqref{eq-disj-yballs}, \eqref{ybinb}, and the triangle inequality for $\rho$, we obtain
\begin{equation}
|Y|\mu(B(o,4D^S))\le 2^{j'a}\sum_{y\in Y}\mu(B(y,D^k))
\end{equation}
\begin{equation}
\le
2^{j'a}\mu(\bigcup_{y\in Y}B(y,D^k))
\le 2^{j'a}\mu(o,4D^S)\, .
\end{equation}

Define the set
\begin{equation}
    \mathcal{C}:= \{(y,k): -S\le k\le S, y\in Y_k\}\,
\end{equation}

Define for {$-S\leq k\leq S$} and $y\in Y_k$
\begin{equation} I_3(y,k):={I_1}(y,k)\cup \left[{I_2}(y,k)\setminus \left[X_k\cup \bigcup\{I_3(y',k):y'\in Y_{k}, y'<y\})\right]\right]
\end{equation}
with
\begin{equation}
      X_{k}:=\bigcup\{I_1(y', k):y'\in Y_{k}\}.
\end{equation}

Let $-S\le l\le k\le S$ and $y\in Y_k$.
    If $l=k$, the inclusion \eqref{3coverdyadic}
    is true from the definition of set union.

It remains to prove
\begin{equation} I_3(y'',k-1)\subset I_3(y,k).
\end{equation}

By the triangle inequality, we have
    \begin{equation}
    \rho(y',x')\le \rho(y',x)+\rho(x,y'')+\rho(y'',x')
    \end{equation}

Using the choice of $x$ and \eqref{squeezedyadic}
    as well as \eqref{yppxp}, we estimate this by
    \begin{equation}
    < 4D^{k'}+4D^{k''}+6D^{k''}\le 6D^{k'}\, ,
    \end{equation}
    where we have used $D>5$ and $k''<k'$.

Adding over $k-K<k'\le k$, and using
\[\mu(I_3(y',k'))\le 2^{4a} \mu(B(y', \frac 14 D^{k'}))\]
from the doubling property \eqref{doublingx} and
\eqref{squeezedyadic} gives
\begin{equation} K\sum_{y'': (y'',k-K|y,k)}
    \mu(I_3(y'',k-K))
\end{equation}
\begin{equation} \le 2^{4a} \sum_{k-K<k'\le k}
   \left[ \sum_{y': (y',k'|y,k)}
\mu(B(y', \frac 14 D^{k'}))\right]
\end{equation}

Assume for the moment all these balls are pairwise disjoint. Then
by additivity of the measure,
\begin{equation}
    K\sum_{y'': (y'',k-K|y,k)}
    \mu(I_3(y'',k-K))
    \le 2^{4a}
\mu(I_3(y,k))\,
\end{equation}
which by $K=2^{4a+1}$ implies \eqref{new-small-boundary}.

Assume then without loss of generality that $l'<l$. Towards a contradiction, assume that
\begin{equation} B(u, \frac 14 D^l)\cap B({u'}, \frac 14 D^{l'})\neq \emptyset
\end{equation}

We write \eqref{very-new-small}
    \begin{equation}
        \sum_{y''\in Y_{k-nK}: (y'',k-nK|y,k)}\mu(I_3(y'',k-nK))
    \end{equation}
    \begin{equation}
        = \sum_{y'\in Y_{k-K}:(y',k-K|y,k)} \left[ \sum_{y''\in Y_{k-nK}: (y'',k-nK|y',k-K)}\mu(I_3(y'',k-nK)) \right]
    \end{equation}

Applying the induction hypothesis, this is bounded by
    \begin{equation}
        = \sum_{y'\in Y_{k-K}:(y',k-K|y,k)} 2^{1-n}\mu(I_3(y',k-K))
    \end{equation}

Define
\begin{equation}
s(I_3(y,k)):=k
\end{equation}
\begin{equation}
c(I_3(y,k)):=y\,.
\end{equation}

Choose a grid structure $(\mathcal{D}, c, s)$ with \Cref{grid-existence}
Let $I \in \mathcal{D}$. Suppose that
\begin{equation} \mathcal{Z} \subset {Q}(X)
\end{equation}
is such that for any ${\vartheta}, {\theta} \in \mathcal{Z}$ with ${\vartheta}\ne {\theta}$ we have
\begin{equation} B_{I^\circ}({\vartheta}, 0.3) \cap B_{I^\circ}({\theta}, 0.3) \cap {Q}(X) = \emptyset\,.
\end{equation}
Since ${Q}(X)$ is finite, there exists a set $\mathcal{Z}$ satisfying both \eqref{eq-tile-Z} and \eqref{eq-tile-disjoint-Z} of maximal cardinality among all such sets. We pick for each $I \in \mathcal{D}$ such a set $\mathcal{Z}(I)$.

We define for all ${\mathfrak p} \in {\mathfrak P}(I_0)$
\begin{equation} {\Omega}({\mathfrak p}) = \Omega_1({\mathfrak p})\,.
\end{equation}
For all other cubes $I \in \mathcal{D}$, $I \ne I_0$, there exists, by \eqref{dyadicproperty} and \eqref{subsetmaxcube}, $J \in \mathcal{D}$ with $I \subset J$ and $I \ne J$. On such $I$ we define $\Omega$ by recursion. We can pick an inclusion minimal $J \in \mathcal{D}$ among the finitely many cubes such that $I \subset J$ and $I \ne J$. This $J$ is unique: Suppose that $J'$ is another inclusion minimal cube with $I \subset J'$ and $I \ne J'$. Without loss of generality, we have that $s(J) \le s(J')$. By \eqref{dyadicproperty}, it follows that $J \subset J'$. Since $J'$ is minimal with respect to inclusion, it follows that $J = J'$. Then we define
\begin{equation} {\Omega}({\mathfrak p}) = \bigcup_{z \in \mathcal{Z}(J) \cap \Omega_1({\mathfrak p})} \Omega((J, z)) \cup B_{{\mathfrak p}}({\mathcal{Q}}({\mathfrak p}),0.2)\,.
\end{equation}

Suppose that ${\vartheta} \in \Omega({\mathfrak p})$. If ${\vartheta}\in B_{{\mathfrak p}}(\mathcal{Q}({\mathfrak p}), 0.2)$, then since
    \begin{equation*}
        B_{{\mathfrak p}}(\mathcal{Q}({\mathfrak p}), 0.2)\subset B_{{\mathfrak p}}(\mathcal{Q}({\mathfrak p}), 1)\, ,
    \end{equation*}
    we conclude that ${\vartheta}\in B_{{\mathfrak p}}(\mathcal{Q}({\mathfrak p}), 0.7)$.

Let
\begin{equation} {\mathfrak P}(k)=\{{\mathfrak p}\in {\mathfrak P} \ : \ {\mathcal{I}}({\mathfrak p})\in \mathcal{C}(G,k)\}
\end{equation}

Define for a collection ${\mathfrak P}'\subset {\mathfrak P}(k)$
\begin{equation} \operatorname{dens}_k' ({\mathfrak P}'):= \sup_{{\mathfrak p}'\in {\mathfrak P}'}\sup_{\lambda \geq 2} \lambda^{-a} \sup_{{\mathfrak p} \in {\mathfrak P}(k): \lambda {\mathfrak p}' \lesssim \lambda {\mathfrak p}}
    \frac{\mu({E}_2(\lambda, {\mathfrak p}))}{\mu({\mathcal{I}}({\mathfrak p}))}\,.
\end{equation}

Following Fefferman \cite{fefferman}, we
define for ${\mathfrak p} \in {\mathfrak C}(k,n)$
\begin{equation} \mathfrak{B}({\mathfrak p}) := \{ \mathfrak{m} \in \mathfrak{M}(k,n) \ : \ 100 {\mathfrak p} \lesssim \mathfrak{m}\}
\end{equation}
and
\begin{equation} {\mathfrak C}_1(k,n,j) := \{{\mathfrak p} \in {\mathfrak C}(k,n) \ : \ 2^{j} \leq |\mathfrak{B}({\mathfrak p})| < 2^{j+1}\}\,.
\end{equation}
and
\begin{equation} {\mathfrak L}_0(k,n) := \{{\mathfrak p} \in {\mathfrak C}(k,n) \ : \ |\mathfrak{B}({\mathfrak p})| <1\}\,.
\end{equation}

Define recursively for $0\le l\le Z(n+1)$
\begin{equation} {\mathfrak L}_1(k,n,j,l)
\end{equation}
to be the set of minimal elements with respect to $\le$ in
\begin{equation}
    {\mathfrak C}_1(k,n,j)\setminus \bigcup_{0\le l'<l}
{\mathfrak L}_1(k,n,j,l')\, .
\end{equation}

Define
\begin{equation} {\mathfrak C}_2(k,n,j):= {\mathfrak C}_1(k,n,j)\setminus \bigcup_{0\le l'\le Z(n+1)}
{\mathfrak L}_1(k,n,j,l')\, .
\end{equation}

Define recursively for $0 \le l \le Z(n+1)$
\begin{equation} {\mathfrak L}_3(k,n,j,l)
\end{equation}
to be the set of all maximal elements with respect to $\le$ in
\begin{equation}
    {\mathfrak C}_3(k,n,j) \setminus \bigcup_{0 \le l' < l} {\mathfrak L}_3(k,n,j,l')\,.
\end{equation}

Define
\begin{equation} \mathcal{L}({\mathfrak u})
\end{equation}
to be the set of all $I \in \mathcal{D}$ with $I \subset {\mathcal{I}}({\mathfrak u})$ and $s(I) = {\mathrm{s}}({\mathfrak u}) - Z(n+1) - 1$ and
\begin{equation}
    B(c(I), 8 D^{s(I)})\not \subset {\mathcal{I}}({\mathfrak u})\, .
\end{equation}

Define ${\mathfrak P}_{F,G}$ to be the set of all ${\mathfrak p}\in {\mathfrak P}$
with
\begin{equation}
    \operatorname{dens}_2(\{{\mathfrak p}\})> 2^{2a+5}\frac{\mu(F)}{\mu(G)}\,.
\end{equation}

Define
\begin{equation} G_1:=\bigcup_{{\mathfrak p}\in {\mathfrak P}_{F,G} }{\mathcal{I}}({\mathfrak p})\, .
\end{equation}

For an integer $\lambda\ge 0$, define $A(\lambda,k,n)$ to be the set
of all $x\in X$ such that
\begin{equation} \sum_{{\mathfrak p} \in \mathfrak{M}(k,n)}\mathbf{1}_{{\mathcal{I}}({\mathfrak p})}(x)>\lambda 2^{n+1}
\end{equation}
and define
\begin{equation} G_2:=
\bigcup_{k\ge 0}\bigcup_{k\le n}
A(2n+6,k,n)\, .
\end{equation}

Define
    \begin{equation} G_3 :=
        \bigcup_{k\ge 0}\, \bigcup_{n \geq k}\,
        \bigcup_{0\le j\le 2n+3}
        \bigcup_{{\mathfrak p} \in {\mathfrak L}_4 (k,n,j)}
        {\mathcal{I}}({\mathfrak p})\, .
     \end{equation}

By maximality
\eqref{mnkmax}
of ${\mathfrak p}'$, we have ${\mathfrak p}'={\mathfrak p}$. This proves the lemma.

Now assume that the statement of \Cref{John-Nirenberg}
is proven for some integer $\lambda\ge 0$.
The set $A(\lambda+1)$ is contained in the set $A(\lambda)$.
Let $\mathcal{M}$ be the set of dyadic cubes which are a subset of $A(\lambda)$. By \Cref{dyadic-union}, the union of $\mathcal{M}$ is $A(\lambda)$.
Let $\mathcal{M}^*$ be the set of maximal dyadic cubes in $\mathcal{M}$.

Let $x\in A(\lambda+1)$ and $L\in \mathcal{M}^*$ such that $x\in L$. Then by the dyadic property \eqref{dyadicproperty}
\begin{equation} \sum_{{\mathfrak p} \in {\mathfrak{M}}(k,n)} \mathbf{1}_{{\mathcal{I}}({\mathfrak p})}(x) =
    \sum_{{\mathfrak p} \in {\mathfrak{M}}(k,n):{\mathcal{I}}({\mathfrak p}) \subset L} \mathbf{1}_{{\mathcal{I}}({\mathfrak p})}(x) +
    \sum_{{\mathfrak p} \in {\mathfrak{M}}(k,n):L \subsetneq {\mathcal{I}}({\mathfrak p})} \mathbf{1}_{{\mathcal{I}}({\mathfrak p})}(x)\,.
\end{equation}
We now show
\begin{equation} \sum_{{\mathfrak p} \in {\mathfrak{M}}(k,n):{\mathcal{I}}({\mathfrak p}) \subset L} \mathbf{1}_{{\mathcal{I}}({\mathfrak p})}(x)\ge 2^{n+1}\,.
\end{equation}
The left-hand side of \eqref{suminout} is strictly greater than $(\lambda+1)2^{n+1}$.
If $L$ is the top cube the second sum $Q_2$ on the right-hand side of \eqref{suminout} is zero and
\eqref{mnkonl} follows immediately. Otherwise consider the inclusion-minimal cube $\hat{L}$ with $L\subsetneq\hat{L}$;
all tiles ${\mathfrak p}$ over which $Q_2$ is summed over satisfy $\hat{L}\subset{\mathfrak p}$, so $Q_2$ is constant for all $x\in\hat{L}$.
By maximality of $L$, $Q_2$ is at most $\lambda 2^{n+1}$ somewhere on $\hat{L}$,
thus on all of $\hat{L}$ and consequently also at $x$. Rearranging the inequality yields \eqref{mnkonl}.

By \Cref{pairwise-disjoint}, we have
\begin{equation}
\sum_{{\mathfrak p} \in {\mathfrak{M}}(k,n):{\mathcal{I}}({\mathfrak p}) \subset L} \mu({E_1}({\mathfrak p})) \leq \mu(L)\, .
\end{equation}
Multiplying by $2^n$ and applying \eqref{ebardense}, we obtain
\begin{equation} \sum_{{\mathfrak p} \in {\mathfrak{M}}(k,n):{\mathcal{I}}({\mathfrak p}) \subset L} \mu({\mathcal{I}}({\mathfrak p})) \leq 2^n \mu(L)\, .
\end{equation}
We then have with \eqref{mnkonl} and \eqref{mnkintl}
\begin{equation}
2^{n+1}\mu(A(\lambda+1)\cap L) =
 \int_{A(\lambda+1)\cap L} 2^{n+1} d\mu
\end{equation}
\begin{equation}
\le
    \int \sum_{{\mathfrak p} \in {\mathfrak{M}}(k,n):{\mathcal{I}}({\mathfrak p}) \subset L} \mathbf{1}_{{\mathcal{I}}({\mathfrak p})} d\mu
\le 2^n \mu(L)\, .
\end{equation}
Hence
\begin{equation}
    2\mu(A(\lambda+1))=2\sum_{L\in \mathcal{M}^*}
\mu(A(\lambda+1)\cap L)\le
\sum_{L\in \mathcal{M}^*}\mu( L)= \mu(A(\lambda))\, .
\end{equation}
Using the induction hypothesis, this proves
\eqref{alambdameasure} for $\lambda+1$ and completes the proof of the lemma.

Let $x\in A(\lambda+1)$ and $L\in \mathcal{M}^*$ such that $x\in L$. Then by the dyadic property \eqref{dyadicproperty}
\begin{equation} \sum_{{\mathfrak p} \in {\mathfrak{M}}(k,n)} \mathbf{1}_{{\mathcal{I}}({\mathfrak p})}(x) =
    \sum_{{\mathfrak p} \in {\mathfrak{M}}(k,n):{\mathcal{I}}({\mathfrak p}) \subset L} \mathbf{1}_{{\mathcal{I}}({\mathfrak p})}(x) +
    \sum_{{\mathfrak p} \in {\mathfrak{M}}(k,n):L \subsetneq {\mathcal{I}}({\mathfrak p})} \mathbf{1}_{{\mathcal{I}}({\mathfrak p})}(x)\,.
\end{equation}

By \Cref{pairwise-disjoint}, we have
\begin{equation}
\sum_{{\mathfrak p} \in {\mathfrak{M}}(k,n):{\mathcal{I}}({\mathfrak p}) \subset L} \mu({E_1}({\mathfrak p})) \leq \mu(L)\, .
\end{equation}
Multiplying by $2^n$ and applying \eqref{ebardense}, we obtain
\begin{equation} \sum_{{\mathfrak p} \in {\mathfrak{M}}(k,n):{\mathcal{I}}({\mathfrak p}) \subset L} \mu({\mathcal{I}}({\mathfrak p})) \leq 2^n \mu(L)\, .
\end{equation}

We then have with \eqref{mnkonl} and \eqref{mnkintl}
\begin{equation}
2^{n+1}\mu(A(\lambda+1)\cap L) =
 \int_{A(\lambda+1)\cap L} 2^{n+1} d\mu
\end{equation}
\begin{equation}
\le
    \int \sum_{{\mathfrak p} \in {\mathfrak{M}}(k,n):{\mathcal{I}}({\mathfrak p}) \subset L} \mathbf{1}_{{\mathcal{I}}({\mathfrak p})} d\mu
\le 2^n \mu(L)\, .
\end{equation}
Hence
\begin{equation}
    2\mu(A(\lambda+1))=2\sum_{L\in \mathcal{M}^*}
\mu(A(\lambda+1)\cap L)\le
\sum_{L\in \mathcal{M}^*}\mu( L)= \mu(A(\lambda))\, .
\end{equation}
Using the induction hypothesis, this proves
\eqref{alambdameasure} for $\lambda+1$ and completes the proof of the lemma.

We write the left-hand side of \eqref{eq-musum}
\begin{equation}
    \int \sum_{\mathfrak{m} \in \mathfrak{M}(k,n)} \mathbf{1}_{{\mathcal{I}}(\mathfrak{m})}(x) \, d\mu(x) \le
2^{n+1} \sum_{\lambda=0}^{|\mathfrak{M}|}\mu(A(\lambda, k,n))\,.
\end{equation}

Using \Cref{John-Nirenberg}
and then summing a geometric series, we estimate this by
\begin{equation}
    \le
2^{n+1}\sum_{\lambda=0}^{|\mathfrak{M}|}
2^{k+1-\lambda}\mu(G)
\le
2^{n+1}2^{k+2}\mu(G)\, .
\end{equation}
This proves the lemma.

If ${\mathfrak u}'$ is a further element in ${\mathfrak U}(\mathfrak{m})$ with ${\mathfrak u}\neq {\mathfrak u}'$, then
