    \begin{equation} + \Bigg| \sum_{s \in \sigma({\mathfrak u}, x)} \int K_s(x,y) (f(y) - P_{\mathcal{J}({\mathfrak T}({\mathfrak u}))} f(y)) \, \mathrm{d}\mu(y) \Bigg|\,.
