     L(x',y) \tilde{\varphi}(x')
    \, \mathrm{d}\mu(y)\right|\,.
\end{equation}
Grouping the second and third and the first and fourth term, we obtain using the definition of $\tilde \varphi$ and Fubini,
\begin{equation} \le \left| \int (L(x',y)-L(x,y)) \varphi(y) \, \mathrm{d}\mu(y)\right|
\end{equation}
\begin{equation} + \left| \int L(x,y) \, \mathrm{d}\mu(y)-\int L(x',y) \, \mathrm{d}\mu(y)\right||\tilde{\varphi}(x')|
\end{equation}
\begin{equation} \le 2 \int |L(x,y) -L(x',y)| \, \mathrm{d}\mu(y)
